int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
    int n = profits.size();
    vector<pair<int, int>> pr(n);  // (capital, profit)
    for (int i = 0; i < n; ++i) pr[i] = {capital[i], profits[i]};
    sort(pr.begin(), pr.end());
    priority_queue<int> avail;  // max-heap of profits we can afford
    int i = 0;
    while (k-- > 0) {
        while (i < n && pr[i].first <= w) avail.push(pr[i++].second);
        if (avail.empty()) break;  // nothing affordable
        w += avail.top();
        avail.pop();
    }
    return w;
}

